{{(() => {
  const ratingsPrincipale = [
    Rating37.value,
		Rating38.value,
		Rating39.value,
		Rating40.value,
    Rating41.value,
		Rating42.value,
		Rating43.value,
		Rating44.value
  ];

  const ratingsGiroMerce = [Rating45.value, Rating46.value];

  const allRatings = [...ratingsPrincipale, ...ratingsGiroMerce];

  const hasInvalidRating = allRatings.some(r => r === null || r === 0);

  if (hasInvalidRating) {
    return "blue";
  }

  const sommaPrincipale = ratingsPrincipale.reduce((acc, val) => acc + val, 0);
  const sommaGiroMerce = ratingsGiroMerce.reduce((acc, val) => acc + val, 0);
  const totale = sommaPrincipale + sommaGiroMerce;

  return totale === 0 ? "" :
    (sommaPrincipale === 24 && sommaGiroMerce >= 4)
      ? "green"
      : "red";
})()
}}
